-2 flex justify-between"><span>Total Skips</span><strong>{{ $total }}</strong></div><div class="flex justify-between"><span>Days Tracked</span><strong>{{ $daysTracked }}</strong></div><div class="flex justify-between"><span>Days With No Skips</span><strong>{{ $daysWithNoSkips }}</strong></div></div><h4 class="mt-5 font-semibold">Activity Summary</h4><ul class="mt-2 space-y-1">@foreach($activities as $activity)<li class="flex justify-between"><span>{{ $activity->name }}</span><span>{{ (int)($monthSkips[$activity->id]??0) }} skips</span></li>@endforeach</ul></div></section></div></div></x-layout>
